def cmp_semver(a, b):
    # Ignore build metadata
    a = a.split('+')[0]
    b = b.split('+')[0]

    # Split off pre-release
    a_parts = a.split('-', 1)
    b_parts = b.split('-', 1)

    a_core = a_parts[0]
    b_core = b_parts[0]
    a_pre = a_parts[1] if len(a_parts) > 1 else None
    b_pre = b_parts[1] if len(b_parts) > 1 else None

    # Compare major.minor.patch numerically
    a_nums = [int(x) for x in a_core.split('.')]
    b_nums = [int(x) for x in b_core.split('.')]
    for x, y in zip(a_nums, b_nums):
        if x < y:
            return -1
        if x > y:
            return 1

    # Pre-release precedence: having one means LOWER precedence
    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    # Compare pre-release identifiers
    a_ids = a_pre.split('.')
    b_ids = b_pre.split('.')

    def _is_numeric(s):
        return len(s) > 0 and all(c in '0123456789' for c in s)

    for i in range(max(len(a_ids), len(b_ids))):
        if i < len(a_ids) and i < len(b_ids):
            ai, bi = a_ids[i], b_ids[i]
            an, bn = _is_numeric(ai), _is_numeric(bi)
            if an and bn:
                if int(ai) < int(bi):
                    return -1
                if int(ai) > int(bi):
                    return 1
            elif an and not bn:
                return -1
            elif not an and bn:
                return 1
            else:
                if ai < bi:
                    return -1
                if ai > bi:
                    return 1
        elif i < len(a_ids):
            return 1
        else:
            return -1

    return 0
```

