import re


def gitignore_match(pattern, path):
    dir_only = pattern.endswith('/')
    if dir_only:
        pattern = pattern[:-1]

    path_is_dir = path.endswith('/')
    if path_is_dir:
        path = path[:-1]

    if dir_only and not path_is_dir:
        return False

    anchored = False
    if pattern.startswith('/'):
        anchored = True
        pattern = pattern[1:]
    elif '/' in pattern:
        anchored = True

    if not pattern:
        return False

    if not anchored and not pattern.startswith('**'):
        pattern = '**/' + pattern

    regex = _pattern_to_regex(pattern)
    return bool(re.fullmatch(regex, path))


def _pattern_to_regex(pattern):
    i = 0
    n = len(pattern)
    result = []

    while i < n:
        c = pattern[i]
        if c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                if i + 2 < n and pattern[i + 2] == '/':
                    result.append('(?:.*/)?')
                    i += 3
                elif i + 2 == n:
                    if i > 0 and pattern[i - 1] == '/':
                        result.append('/.*')
                    else:
                        result.append('.*')
                    i += 2
                else:
                    result.append('.*')
                    i += 2
            else:
                result.append('[^/]*')
                i += 1
        elif c == '?':
            result.append('[^/]')
            i += 1
        elif c == '[':
            j = i + 1
            if j < n and pattern[j] == '!':
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j < n:
                inner = pattern[i + 1:j]
                if inner.startswith('!'):
                    inner = '^' + inner[1:]
                result.append('[' + inner + ']')
                i = j + 1
            else:
                result.append(re.escape('['))
                i += 1
        else:
            result.append(re.escape(c))
            i += 1

    return ''.join(result)
