def parse_range(header, size):
    if not isinstance(header, str):
        return None

    header = header.strip()
    if not header.startswith("bytes="):
        return None

    ranges_str = header[6:].strip()
    if not ranges_str:
        return None

    results = []
    for part in ranges_str.split(","):
        part = part.strip()
        if not part or "-" not in part:
            return None

        left, right = part.split("-", 1)
        left = left.strip()
        right = right.strip()

        if left and not left.isdigit():
            return None
        if right and not right.isdigit():
            return None
        if not left and not right:
            return None

        if left and right:
            start = int(left)
            end = int(right)
            if start > end:
                continue
            if start >= size:
                continue
            end = min(end, size - 1)
            if start > end:
                continue
            results.append((start, end))
        elif left:
            start = int(left)
            if start >= size:
                continue
            results.append((start, size - 1))
        else:
            suffix = int(right)
            if size == 0:
                continue
            start = max(0, size - suffix)
            results.append((start, size - 1))

    if not results:
        return None
    return results
```

