def unified_diff(a, b, context=3):
    if a == b:
        return []

    n, m = len(a), len(b)

    # LCS DP table
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack to build operation list
    ops = []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i - 1] == b[j - 1]:
            ops.append(('equal', i - 1, j - 1))
            i -= 1
            j -= 1
        elif i > 0 and (j == 0 or dp[i - 1][j] >= dp[i][j - 1]):
            ops.append(('delete', i - 1, None))
            i -= 1
        else:
            ops.append(('insert', None, j - 1))
            j -= 1
    ops.reverse()

    # Identify maximal runs of non-equal ops
    block_ranges = []
    cur = None
    for idx, op in enumerate(ops):
        if op[0] != 'equal':
            if cur is None:
                cur = idx
        else:
            if cur is not None:
                block_ranges.append((cur, idx - 1))
                cur = None
    if cur is not None:
        block_ranges.append((cur, len(ops) - 1))

    if not block_ranges:
        return []

    # Extend each block with up to `context` equal lines on each side
    extended = []
    for start, end in block_ranges:
        cb = 0
        while cb < context and start - cb - 1 >= 0 and ops[start - cb - 1][0] == 'equal':
            cb += 1
        ca = 0
        while ca < context and end + ca + 1 < len(ops) and ops[end + ca + 1][0] == 'equal':
            ca += 1
        extended.append((start - cb, end + ca))

    # Merge overlapping or adjacent hunks
    merged = []
    for s, e in extended:
        if merged and s <= merged[-1][1] + 1:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))

    # Emit output
    result = []
    for start, end in merged:
        hunk = ops[start:end + 1]

        a_lines = [op for op in hunk if op[0] in ('equal', 'delete')]
        b_lines = [op for op in hunk if op[0] in ('equal', 'insert')]

        if a_lines:
            a_start = a_lines[0][1] + 1
        else:
            a_start = 0
            for idx in range(start - 1, -1, -1):
                if ops[idx][1] is not None:
                    a_start = ops[idx][1] + 1
                    break

        if b_lines:
            b_start = b_lines[0][1] + 1
        else:
            b_start = 0
            for idx in range(start - 1, -1, -1):
                if ops[idx][2] is not None:
                    b_start = ops[idx][2] + 1
                    break

        a_len = len(a_lines)
        b_len = len(b_lines)

        result.append(f"@@ -{a_start},{a_len} +{b_start},{b_len} @@")

        for op in hunk:
            if op[0] == 'equal':
                result.append(f" {a[op[1]]}")
            elif op[0] == 'delete':
                result.append(f"-{a[op[1]]}")
            else:
                result.append(f"+{b[op[1]]}")

    return result
