from collections import OrderedDict


class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.key_to_node = {}
        self.freq_to_list = {}
        self.min_freq = 0

    def _remove(self, key, freq):
        self.freq_to_list[freq].pop(key)
        if not self.freq_to_list[freq]:
            del self.freq_to_list[freq]
            if self.min_freq == freq:
                self.min_freq = freq + 1

    def _add(self, key, freq):
        if freq not in self.freq_to_list:
            self.freq_to_list[freq] = OrderedDict()
        self.freq_to_list[freq][key] = True

    def get(self, key):
        if key not in self.key_to_node:
            return -1
        val, freq = self.key_to_node[key]
        self._remove(key, freq)
        self._add(key, freq + 1)
        self.key_to_node[key] = [val, freq + 1]
        return val

    def put(self, key, value):
        if self.capacity == 0:
            return
        if key in self.key_to_node:
            _, freq = self.key_to_node[key]
            self._remove(key, freq)
            self._add(key, freq + 1)
            self.key_to_node[key] = [value, freq + 1]
        else:
            if len(self.key_to_node) >= self.capacity:
                evict_key, _ = self.freq_to_list[self.min_freq].popitem(last=False)
                if not self.freq_to_list[self.min_freq]:
                    del self.freq_to_list[self.min_freq]
                del self.key_to_node[evict_key]
            self._add(key, 1)
            self.key_to_node[key] = [value, 1]
            self.min_freq = 1
