import heapq

def topk(stream, k):
    if k <= 0:
        return []

    heap = []
    arrival = 0

    for value, label in stream:
        if len(heap) < k:
            heapq.heappush(heap, (value, -arrival, label))
        else:
            if value > heap[0][0]:
                heapq.heapreplace(heap, (value, -arrival, label))
        arrival += 1

    heap.sort(key=lambda x: (-x[0], -x[1]))
    return [(v, l) for v, _, l in heap]
