import heapq
from collections import defaultdict

def window_medians(a, k):
    n = len(a)
    if k > n:
        return []

    lo = []  # max-heap (negated values)
    hi = []  # min-heap
    delayed = defaultdict(int)

    def clean(heap, is_lo):
        while heap:
            val = -heap[0] if is_lo else heap[0]
            if val in delayed:
                delayed[val] -= 1
                if delayed[val] == 0:
                    del delayed[val]
                heapq.heappop(heap)
            else:
                break

    def balance():
        if len(lo) > len(hi) + 1:
            heapq.heappush(hi, -heapq.heappop(lo))
            clean(lo, True)
        elif len(hi) > len(lo):
            heapq.heappush(lo, -heapq.heappop(hi))
            clean(hi, False)

    def add(x):
        if lo and x > -lo[0]:
            heapq.heappush(hi, x)
        else:
            heapq.heappush(lo, -x)
        balance()

    def remove(x):
        delayed[x] += 1
        if x <= -lo[0]:
            heapq.heappush(lo, -x)
            clean(lo, True)
        else:
            heapq.heappush(hi, x)
            clean(hi, False)
        balance()

    for i in range(k):
        add(a[i])

    result = []
    if k % 2 == 1:
        result.append(float(-lo[0]))
    else:
        result.append((float(-lo[0]) + float(hi[0])) / 2.0)

    for i in range(k, n):
        remove(a[i - k])
        add(a[i])
        if k % 2 == 1:
            result.append(float(-lo[0]))
        else:
            result.append((float(-lo[0]) + float(hi[0])) / 2.0)

    return result
