class RollbackDSU:
    def __init__(self, n):
        self.n = n
        self._parent = list(range(n))
        self._size = [1] * n
        self._components = n
        self._history = []  # each entry: (child_root, parent_root, old_parent_size)

    def find(self, x):
        while self._parent[x] != x:
            x = self._parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        # Union by size: attach smaller tree under larger tree
        if self._size[ra] < self._size[rb]:
            ra, rb = rb, ra
        self._history.append((rb, ra, self._size[ra]))
        self._parent[rb] = ra
        self._size[ra] += self._size[rb]
        self._components -= 1
        return True

    def snapshot(self):
        return len(self._history)

    def rollback(self, token):
        while len(self._history) > token:
            child, parent, old_parent_size = self._history.pop()
            self._parent[child] = child
            self._size[parent] = old_parent_size
            self._components += 1

    def components(self):
        return self._components
