        node = self._root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = _TrieNode()
            node = node.children[ch]
        node.count += 1

    def remove(self, word):
        node = self._root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        if node.count == 0:
            return False
        node.count -= 1
        return True

    def search(self, pattern):
        results = []
        self._search(self._root, pattern, 0, '', results)
        return sorted(results)

    def _search(self, node, pattern, idx, path, results):
        if idx == len(pattern):
            if node.count > 0:
                results.append(path)
            return
        ch = pattern[idx]
        if ch == '.':
            for c, child in node.children.items():
                self._search(child, pattern, idx + 1, path + c, results)
        else:
            child = node.children.get(ch)
            if child is not None:
                self._search(child, pattern, idx + 1, path + ch, results)
