def to_base(n, alphabet):
    base = len(alphabet)
    if n == 0:
        return alphabet[0]
    negative = n < 0
    n = abs(n)
    digits = []
    while n > 0:
        n, r = divmod(n, base)
        digits.append(alphabet[r])
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))


def from_base(s, alphabet):
    if not s:
        raise ValueError("empty string")
    base = len(alphabet)
    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
    if not s:
        raise ValueError("empty string")
    digit_map = {c: i for i, c in enumerate(alphabet)}
    result = 0
    for c in s:
        if c not in digit_map:
            raise ValueError(f"invalid character: {c!r}")
        result = result * base + digit_map[c]
