import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    heap = [(0, 0, (src,), src)]
    best = {src: (0, 0, (src,))}

    while heap:
        cost, edges, path, node = heapq.heappop(heap)

        if node in best:
            bcost, bedges, bpath = best[node]
            if (cost, edges, path) > (bcost, bedges, bpath):
                continue

        if node == dst:
            return (cost, list(path))

        for neighbor, weight in graph.get(node, []):
            new_cost = cost + weight
            new_edges = edges + 1
            new_path = path + (neighbor,)

            if neighbor not in best or (new_cost, new_edges, new_path) < best[neighbor]:
                best[neighbor] = (new_cost, new_edges, new_path)
                heapq.heappush(heap, (new_cost, new_edges, new_path, neighbor))

    return (None, [])
