    const listeners = this._events.get(event);
    if (!listeners) return;
    for (let i = listeners.length - 1; i >= 0; i--) {
      if (listeners[i].fn === fn && !listeners[i].removed) {
        listeners[i].removed = true;
        listeners.splice(i, 1);
      }
    }
