        if (idx !== -1) listeners.splice(idx, 1);
      }

      try {
        entry.fn(...args);
        count++;
      } catch (err) {
        if (firstError === null) firstError = err;
        count++;
      }
    }

    if (firstError !== null) throw firstError;
    return count;
  }
}

