      let anyAlive = false;

      for (let i = 0; i < iterators.length; i++) {
        if (exhausted[i]) {
          row.push(fill);
        } else {
          const result = iterators[i].next();
          if (result.done) {
            exhausted[i] = true;
            row.push(fill);
