function toposortTasks(tasks) {
  const names = Object.keys(tasks);

  for (const name of names) {
    for (const dep of tasks[name].deps) {
      if (!(dep in tasks)) {
        return Promise.reject(new Error(`Unknown dependency: ${dep}`));
      }
    }
  }

  const WHITE = 0, GRAY = 1, BLACK = 2;
  const color = {};
  for (const name of names) color[name] = WHITE;

  function dfs(node) {
    color[node] = GRAY;
    for (const dep of tasks[node].deps) {
      if (color[dep] === GRAY) {
        throw new Error('Dependency cycle detected');
      }
      if (color[dep] === WHITE) {
        dfs(dep);
      }
    }
    color[node] = BLACK;
  }

  for (const name of names) {
    if (color[name] === WHITE) dfs(name);
  }

  const results = {};
  const promises = {};

  for (const name of names) {
    promises[name] = (async () => {
      const depValues = {};
      for (const dep of tasks[name].deps) {
        depValues[dep] = await promises[dep];
      }
      const value = await tasks[name].run(depValues);
      results[name] = value;
      return value;
    })();
  }

  return Promise.all(names.map((name) => promises[name])).then(() => results);
}

module.exports = toposortTasks;
