export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<string, Set<(payload: never) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    const key = k as string;
    let set = this.handlers.get(key);
    if (!set) {
      set = new Set();
      this.handlers.set(key, set);
    }
    set.add(fn);
    return () => {
      set!.delete(fn);
    };
  }

  emit<K extends keyof E>(...args: E[K] extends void ? [k: K] : [k: K, payload: E[K]]): void {
    const key = args[0] as string;
    const payload = args[1] as E[K] | undefined;
    const set = this.handlers.get(key);
    if (set) {
      for (const fn of set) {
        fn(payload as never);
      }
    }
  }
}
