type StripLeading<S extends string> =
  S extends `${'_' | '-'}${infer R}` ? StripLeading<R> : S;

type CamelCaseInner<S extends string, Upper extends boolean = false> =
  S extends `${infer F}${infer R}`
    ? F extends '_' | '-'
      ? CamelCaseInner<R, true>
      : Upper extends true
        ? `${Capitalize<F>}${CamelCaseInner<R, false>}`
        : `${F}${CamelCaseInner<R, false>}`
    : '';

type CamelCase<S extends string> = CamelCaseInner<StripLeading<S>>;

type SnakeCase<S extends string, First extends boolean = true> =
  S extends `${infer F}${infer R}`
    ? F extends Uppercase<F>
      ? Lowercase<F> extends F
        ? `${F}${SnakeCase<R, false>}`
        : First extends true
          ? `${Lowercase<F>}${SnakeCase<R, false>}`
          : `_${Lowercase<F>}${SnakeCase<R, false>}`
      : `${F}${SnakeCase<R, false>}`
    : '';

type CamelKeys<T> = {
  [K in keyof T as CamelCase<K & string>]: T[K];
};

export { CamelCase, SnakeCase, CamelKeys };
