// sol.ts

export interface Ok<T, E> {
  readonly tag: "ok";
  readonly value: T;
}

export interface Err<T, E> {
  readonly tag: "err";
  readonly error: E;
}

export type Result<T, E> = Ok<T, E> | Err<T, E>;

export function ok<T, E = unknown>(value: T): Result<T, E> {
  return { tag: "ok", value };
}

export function err<T = unknown, E>(error: E): Result<T, E> {
  return { tag: "err", error };
}

export function isOk<T, E>(r: Result<T, E>): r is Ok<T, E> {
  return r.tag === "ok";
}

export function isErr<T, E>(r: Result<T, E>): r is Err<T, E> {
  return r.tag === "err";
}

export function map<T, E, U>(r: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  if (isOk(r)) {
    return ok<U, E>(fn(r.value));
  }
  return r;
}

export function unwrapOr<T, E>(r: Result<T, E>, fallback: T): T {
  if (isOk(r)) {
    return r.value;
  }
  return fallback;
}
