type SplitChars<S extends string> =
  S extends '' ? [] :
  S extends `${infer C}${infer Rest}` ? [C, ...SplitChars<Rest>] : never;

export type Split<S extends string, D extends string> =
  S extends '' ? [''] :
  D extends '' ? SplitChars<S> :
  S extends `${infer Head}${D}${infer Tail}` ? [Head, ...Split<Tail, D>] :
  [S];

export type Join<T extends readonly string[], D extends string> =
  T extends [infer First, ...infer Rest]
    ? Rest extends [] ? First : `${First}${D}${Join<Rest, D>}`
    : '';

type TrimLeft<S extends string> =
  S extends ` ${infer Rest}` ? TrimLeft<Rest> : S;

type TrimRight<S extends string> =
  S extends `${infer Rest} ` ? TrimRight<Rest> : S;

export type Trim<S extends string> = TrimLeft<TrimRight<S>>;
