  S extends `${infer Head}${Sep}${infer Tail}`
    ? [Head, ...Split<Tail, Sep>]
    : [S];

type ExtractParamNames<Segments extends string[]> =
  Segments extends [infer Head extends string, ...infer Tail extends string[]]
    ? Head extends `:${infer Name}`
      ? [Name, ...ExtractParamNames<Tail>]
      : ExtractParamNames<Tail>
    : [];

type BuildParams<Names extends string[]> =
  Names extends [infer Head extends string, ...infer Tail extends string[]]
    ? { [K in Head]: string } & BuildParams<Tail>
    : {};

type RouteFn<Params extends Record<string, string>> =
  keyof Params extends never
    ? () => string
    : (params: Params) => string;

type DefineRoutes<Routes extends Record<string, string>> = {
  [K in keyof Routes]: RouteFn<BuildParams<ExtractParamNames<Split<Routes[K], '/'>>>>;
};

export function defineRoutes<Routes extends Record<string, string>>(
  routes: Routes,
): DefineRoutes<Routes> {
  const result: Record<string, (params?: Record<string, string>) => string> = {};

  for (const [name, path] of Object.entries(routes)) {
    result[name] = (params = {}) =>
      path.replace(/:(\w+)/g, (_, key) => params[key] ?? `:${key}`);
  }

  return result as unknown as DefineRoutes<Routes>;
}
